var a=`1318-pascualina`;var n=`world-1318`;var t=`UY`;var o=`south-america`;var s=8;var r=90;var l={en:`Pascualina`,ua:`Паскуаліна`};var u={en:`Pascualina is a dish from Uruguay featuring all-purpose flour, spinach, yellow onion, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Паскуаліна, страва кухні країни Уругвай з такими основними складниками: пшеничне борошно універсальне, шпинат, жовта цибуля, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`all-purpose-flour`,440,`g`],[`olive-oil`,75,`ml`],[`water`,230,`ml`],[`table-salt`,7,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`spinach`,620,`g`],[`yellow-onion`,170,`g`],[`garlic`,4,`clove`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`ricotta`,350,`g`],[`chicken-egg`,4,`pcs`],[`parmigiano-reggiano`,100,`g`]]},{en:`Layer the previously prepared components evenly inside a baking dish, serving mold or plate appropriate to the recipe; smooth the surface and avoid mixing the layers.`,ua:`Рівномірно викладіть підготовлені компоненти шарами у формі для запікання, подавання чи на тарілці відповідно до страви; вирівняйте поверхню, не змішуючи шари.`,t:[`layered-assembly`],m:12,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 45 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 45 хвилин до готовності.`,t:[`baking`],m:45,i:[]}];var g={slug:a,id:n,country:`UY`,region:o,servings:8,minutes:90,title:l,text:u,steps:d};export{t as country,g as default,n as id,r as minutes,o as region,s as servings,a as slug,d as steps,u as text,l as title};